import dimensions from "@/lib/content/photo-dimensions.json";

/** Pixel size of every source photo, keyed by R2 key ("rooms/rooms_76.jpg"). Generated by scripts/photo-dimensions.ts. */
export const PHOTO_DIMENSIONS: Record<string, { w: number; h: number }> = dimensions;

/** Recorded size of an old-site photo; undefined for a staff upload (own keys only, never Object.prototype's). */
function sizeOf(key: string): { w: number; h: number } | undefined {
  return Object.hasOwn(PHOTO_DIMENSIONS, key) ? PHOTO_DIMENSIONS[key] : undefined;
}

/** Sharpness rule: source must be at least `tolerance` x the display slot in BOTH dimensions. Unknown key: false. */
export function photoFits(key: string, slot: { w: number; h: number }, tolerance = 1.5): boolean {
  const src = sizeOf(key);
  if (!src) return false;
  return src.w >= slot.w * tolerance && src.h >= slot.h * tolerance;
}

/** Largest display height (rounded down) that still fits at `slotWidth`; 0 if unknown or the width alone is too large. */
export function maxSlotHeight(key: string, slotWidth: number, tolerance = 1.5): number {
  const src = sizeOf(key);
  if (!src || src.w < slotWidth * tolerance) return 0;
  return Math.floor(src.h / tolerance);
}

/**
 * Height for a cover-fit frame `slotWidth` wide: the sharp maximum (`maxSlotHeight`), capped at the frame's own
 * design maximum `cap`. 0 means the source cannot fill this slot sharply; put it in a smaller slot.
 */
export function frameHeight(key: string, slotWidth: number, cap: number, tolerance = 1.5): number {
  const h = maxSlotHeight(key, slotWidth, tolerance);
  return h === 0 ? 0 : Math.min(cap, h);
}

/**
 * The frame for `key` in a slot `slotWidth` wide with design height maximum `cap`.
 *
 * A known old-site photo gets its largest sharp frame: `maxW` = source.w / tolerance (never display wider),
 * `h` = min(cap, source.h / tolerance), and `fits` = whether the source can fill the whole slot width.
 *
 * A key not in PHOTO_DIMENSIONS is a staff upload (lib/admin/uploads.ts records no dimensions; its WebP variants go
 * up to 1100px), so it is trusted and gets the slot's own box: `{ known: false, fits: true, maxW: slotWidth, h: cap }`.
 */
export function frameBox(key: string, slotWidth: number, cap: number, tolerance = 1.5): { known: boolean; fits: boolean; maxW: number; h: number } {
  const src = sizeOf(key);
  if (!src) return { known: false, fits: true, maxW: slotWidth, h: cap };
  const maxW = Math.floor(src.w / tolerance);
  return { known: true, fits: maxW >= slotWidth, maxW, h: Math.min(cap, Math.floor(src.h / tolerance)) };
}

/**
 * The first of `keys` that can fill `slot`: a staff upload (unknown key, trusted) or a known photo that passes the
 * sharpness rule in both dimensions. null when none can, so the caller leaves that slot out.
 */
export function pickFitting(keys: readonly string[], slot: { w: number; h: number }, tolerance = 1.5): string | null {
  return keys.find((k) => !sizeOf(k) || photoFits(k, slot, tolerance)) ?? null;
}
